// Server to server request authentication (CDC 3.10). Source of truth: /shared. Copies are generated by `npm run sync-shared`.
// Headers: x-sq-ts (ISO timestamp), x-sq-nonce (16 random bytes, hex), x-sq-sig (hex).
// x-sq-sig = HMAC-SHA256(pair secret, method \n path \n timestamp \n nonce \n SHA256(body) in hex).
// `path` is the URL path plus the query string, exactly as sent (for example /api/bank-account?sqRef=...).
import { createHash, createHmac, randomBytes, timingSafeEqual } from "node:crypto";

export const HMAC_HEADER_TS = "x-sq-ts";
export const HMAC_HEADER_NONCE = "x-sq-nonce";
export const HMAC_HEADER_SIG = "x-sq-sig";
export const HMAC_MAX_SKEW_MS = 60_000;
/** Nonces can be deleted once they are older than this (CDC 3.10: 10 minutes). */
export const HMAC_NONCE_TTL_MS = 10 * 60_000;

/** Replay protection. `claim` records the nonce and resolves true only the first time it is seen. */
export interface NonceStore {
  claim(nonce: string, now: Date): Promise<boolean>;
}

export type HmacFailure = "NOT_CONFIGURED" | "MISSING_HEADERS" | "BAD_TIMESTAMP" | "STALE_TIMESTAMP" | "BAD_NONCE" | "BAD_SIGNATURE" | "REPLAYED_NONCE";
export type HmacResult = { ok: true } | { ok: false; reason: HmacFailure };

export type SignInput = { secret: string; method: string; path: string; body?: string; now?: Date; nonce?: string };
export type VerifyInput = {
  secret: string | undefined;
  method: string;
  path: string;
  body?: string;
  headers: { get(name: string): string | null };
  nonces: NonceStore;
  now?: Date;
};

function mac(secret: string, method: string, path: string, ts: string, nonce: string, body: string): Buffer {
  const bodyHash = createHash("sha256").update(body, "utf8").digest("hex");
  return createHmac("sha256", secret).update([method.toUpperCase(), path, ts, nonce, bodyHash].join("\n"), "utf8").digest();
}

/** Returns the three headers to add to an outgoing request. */
export function signRequest({ secret, method, path, body = "", now = new Date(), nonce = randomBytes(16).toString("hex") }: SignInput): Record<string, string> {
  if (!secret) throw new Error("HMAC secret is not configured");
  const ts = now.toISOString();
  return { [HMAC_HEADER_TS]: ts, [HMAC_HEADER_NONCE]: nonce, [HMAC_HEADER_SIG]: mac(secret, method, path, ts, nonce, body).toString("hex") };
}

/** Verifies an incoming request. Fails closed without a secret. The nonce is claimed only after the signature is valid. */
export async function verifyRequest({ secret, method, path, body = "", headers, nonces, now = new Date() }: VerifyInput): Promise<HmacResult> {
  if (!secret) return { ok: false, reason: "NOT_CONFIGURED" };
  const ts = headers.get(HMAC_HEADER_TS);
  const nonce = headers.get(HMAC_HEADER_NONCE);
  const sig = headers.get(HMAC_HEADER_SIG);
  if (!ts || !nonce || !sig) return { ok: false, reason: "MISSING_HEADERS" };
  const sent = Date.parse(ts);
  if (Number.isNaN(sent)) return { ok: false, reason: "BAD_TIMESTAMP" };
  if (Math.abs(now.getTime() - sent) > HMAC_MAX_SKEW_MS) return { ok: false, reason: "STALE_TIMESTAMP" };
  if (!/^[0-9a-f]{32}$/.test(nonce)) return { ok: false, reason: "BAD_NONCE" };
  if (!/^[0-9a-f]{64}$/.test(sig)) return { ok: false, reason: "BAD_SIGNATURE" };
  const expected = mac(secret, method, path, ts, nonce, body);
  if (!timingSafeEqual(expected, Buffer.from(sig, "hex"))) return { ok: false, reason: "BAD_SIGNATURE" };
  if (!(await nonces.claim(nonce, now))) return { ok: false, reason: "REPLAYED_NONCE" };
  return { ok: true };
}

/** In-memory nonce store for tests and local development. Forgets nonces older than the TTL. */
export class MemoryNonceStore implements NonceStore {
  private seen = new Map<string, number>();
  async claim(nonce: string, now: Date): Promise<boolean> {
    const t = now.getTime();
    for (const [n, at] of this.seen) if (t - at > HMAC_NONCE_TTL_MS) this.seen.delete(n);
    if (this.seen.has(nonce)) return false;
    this.seen.set(nonce, t);
    return true;
  }
}
